scripts.卢青.txt:
//和卢青对话

	Say("卢青：师兄！", 83);
	Say("独孤剑：师弟！是你！你怎么到这里来了", 1);
	Say("卢青：师兄，你一出门就是数月，师弟师妹们没有你的消息，大家都着急死了，所以推我出来打探你的消息。", 83);
	Say("独孤剑：让你们挂记了。不过我已经打探到一些消息，师傅果然是被五色教的人害死的。五色教勾结金国，欲对我大宋不利，他们还害死了武夷的柳前辈和华山的顾大侠……眼下我还有些事情要办，应该不久就可以回衡山。你先回山等我吧！", 1);
	Say("卢青：我们一起想办法给师傅报仇吧！", 83);
	Say("独孤剑：仇自然要报，不过眼前还有更大的阴谋，我们要小心应付。师弟师妹们还好吧！", 2);
	Say("卢青：大家都好，只是日夜盼着师兄回山……对了，这是师傅留下的“丹心剑”，我担心师兄，就把它带来了。", 83);
	Say("独孤剑：多谢你了，现在正用得着它呢。", 2);
	Say("卢青：师兄……呃……", 83);
	Say("卢青：这个……", 83);
	Say("独孤剑：什么事情婆婆妈妈的？男子汉大丈夫……", 8);
	Say("卢青：这位姑娘是……", 83);
	Say("独孤剑：……这，对了，这……这位是张琳心张姑娘。", 4);
	Say("独孤剑：……琳心，这是我师弟卢青。", 4);
	Say("卢青：卢青拜见掌门——大嫂！", 83);
	Say("张琳心：……", 22);
	Say("独孤剑：师弟，你说什么？！", 4);
	Say("卢青：师弟们虽然在山上，可是耳朵也没有闲着。师兄，你就不用婆婆妈妈了，男子汉大丈夫……", 83);
	Say("独孤剑：臭小子，我回山再收拾你们……好了，你快回山去！", 9);
	Say("卢青：谨遵掌门法旨——嫂子，我们在衡山都替你打点好了！", 83);
	Say("张琳心：……", 22);
	Say("独孤剑：你……", 4);
	Say("卢青：我就走，就走……只怕曲霞妹子要哭鼻子了！", 83);
	NpcGotoEx(卢青, *,*);
	Say("独孤剑：……", 4);
	Say("琳心：……独孤大哥，我们……先去客栈休息吧！", 22);
	Say("独孤剑：嗯……", 1);
	
	
	FadeOut();
	DelNpc(卢青);
	SaveNpc();
	SaveObj();
	LoadMap("map085_朱仙镇客栈.map");
	LoadNpc("map075.npc");
	LoadObj("map075.obj");
	SetPlayerPos(*, *);
	SetPlayerDir(*);
	SetNpcPos(张琳心,*,*);
	FullLife();
	FullMana();
	FullThew();
	AddGoods("丹心剑.ini");
	Assign($Event, 440);
	Assign($Talkluqing, 1);
	Memo("独孤剑和张琳心返回朱仙镇，遇见师弟卢青，卢青将丹心剑交给了独孤剑。");
	
	GetMoneyNum();
	If($MoneyNum << 10) @NotenoughMon;
	If($MoneyNum >= 10) @EnoughMon;
@NotenoughMon:
	SetMoneyNum(0);
	Goto @End;
@EnoughMon:
	AddMoney(-10);
	Goto @End;	
@End:	
	FadeIn();
	Say("在客栈中休息了一夜,觉得精神奕奕。");
	Return;

